// SPDX-License-Identifier: MIT
import assert from 'node:assert/strict';
import { mkdtempSync, mkdirSync, rmSync, writeFileSync } from 'node:fs';
import { tmpdir } from 'node:os';
import { join } from 'node:path';
import { spawnSync } from 'node:child_process';
import { fileURLToPath } from 'node:url';

const checker = fileURLToPath(new URL('./check-links.mjs', import.meta.url));
const root = mkdtempSync(join(tmpdir(), 'check-links-'));

function run(name, markdown) {
  const directory = join(root, name);
  mkdirSync(directory);
  writeFileSync(join(directory, 'page.md'), markdown);
  return spawnSync(process.execPath, [checker, directory], { encoding: 'utf8' });
}

try {
  const valid = join(root, 'valid');
  mkdirSync(valid);
  writeFileSync(join(valid, 'file.md'), '# File');
  mkdirSync(join(valid, 'readme-dir'));
  writeFileSync(join(valid, 'readme-dir', 'README.md'), '# Readme');
  mkdirSync(join(valid, 'index-dir'));
  writeFileSync(join(valid, 'index-dir', 'index.md'), '# Index');
  writeFileSync(join(valid, 'page.md'), '[file](file.md) [readme](readme-dir) [index](index-dir)\n\n```md\n[ignored](missing-dir)\n```\n');
  const positive = spawnSync(process.execPath, [checker, valid], { encoding: 'utf8' });
  assert.equal(positive.status, 0, positive.stderr);
  assert.match(positive.stdout, /Checked 3 local Markdown links\./);

  const negative = run('invalid', '[empty](empty-dir) [missing](missing.md)\n');
  mkdirSync(join(root, 'invalid', 'empty-dir'));
  assert.equal(negative.status, 1);
  assert.match(negative.stderr, /empty-dir/);
  assert.match(negative.stderr, /missing\.md/);
  console.log('check-links positive and negative cases passed.');
} finally {
  rmSync(root, { recursive: true, force: true });
}

